const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/latest-");
fs.writeFileSync(path.join(dir, "index.js"), "export default { fetch() { return new Response('ok'); } };\n");
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "deploy", "index.js", "--name", "t", "--dry-run", "--latest", "--outdir", "out"], {
  cwd: dir, encoding: "utf8", timeout: 80000,
  env: { ...process.env, CI: "1", WRANGLER_SEND_METRICS: "false", NO_COLOR: "1", FORCE_COLOR: "0" }
});
const out = (r.stdout || "") + (r.stderr || "");
const m = out.match(/Using the latest compatibility date supported by this version of Wrangler \((\d{4}-\d{2}-\d{2})\)/);
if (!m) {
  if (out.includes("Using the latest version of the Workers runtime")) symptom("deploy --latest names no supported compatibility date, it uses the latest runtime date");
  broken("no --latest warning in output: " + out.slice(0, 600));
}
const today = new Date().toISOString().slice(0, 10);
if (!(m[1] < today)) broken("--latest resolved to " + m[1] + ", not earlier than today " + today);
console.log("OK: deploy --latest resolved to " + m[1] + ", the date supported by the installed runtime, not today " + today);

